Sure, I'd be happy to help you with that! Here's a Python program that simulates an employee database using both `for` and `while` loops. This program allows you to add, view, and delete employees from the database.

```python
# Employee database
employee_db = {}

def add_employee():
    """Add an employee to the database."""
    name = input("Enter employee name: ").strip()
    if name in employee_db:
        print(f"Employee {name} already exists. Please choose another name.")
        return

    job_title = input("Enter job title: ").strip()
    salary = float(input("Enter salary: ").strip())

    employee_db[name] = {
        "job_title": job_title,
        "salary": salary
    }

    print(f"Employee {name} added successfully.")

def view_employees():
    """View all employees in the database."""
    for name, employee_data in employee_db.items():
        print(f"{name}: Job Title: {employee_data['job_title']}, Salary: {employee_data['salary']}")

def delete_employee():
    """Delete an employee from the database."""
    name_to_delete = input("Enter employee name to delete: ").strip()

    if name_to_delete not in employee_db:
        print(f"Employee {name_to_delete} not found in the database.")
        return

    del employee_db[name_to_delete]
    print(f"Employee {name_to_delete} deleted successfully.")

# Main menu
while True:
    print("\nEmployee Database Menu:")
    print("1. Add employee")
    print("2. View employees")
    print("3. Delete employee")
    print("4. Exit")

    choice = input("Enter your choice: ").strip()

    if choice == "1":
        add_employee()
    elif choice == "2":
        view_employees()
    elif choice == "3":
        delete_employee()
    elif choice == "4":
        break
    else:
        print("Invalid choice. Please try again.")

print("Goodbye!")
```

This program will keep asking for user input until the user chooses to exit. The `add_employee`, `view_employees`, and `delete_employee` functions allow you to interact with the database using `for` and `while` loops.
